import {evaluate} from './pose-rules.mjs';
const $=id=>document.getElementById(id);
const poses=[
{id:'reach',name:'Overhead reach',type:'stretch',area:'UPPER BODY',icon:'↟',description:'Create a little length through your arms and upper body.',cues:['Stand comfortably, feet about hip-width apart.','Reach both arms up without lifting your ribs.','Keep your shoulders easy. Breathe naturally.']},
{id:'side',name:'Standing side bend',type:'stretch',area:'SIDE BODY',icon:'⤴',description:'A gentle reach to open up the side of your body.',cues:['Stand with both feet grounded and knees soft.','Reach one arm up and lean a little to the side.','Keep facing forward. Repeat on the other side.']},
{id:'mountain',name:'Mountain pose',type:'yoga',area:'TADASANA',icon:'△',description:'Find a steady foundation and a moment of stillness.',cues:['Stand tall with your feet comfortably apart.','Let your arms rest, shoulders relaxed.','Balance your weight across both feet.']},
{id:'warrior',name:'Warrior II',type:'yoga',area:'VIRABHADRASANA II',icon:'✛',description:'A grounded stance with a gentle, open reach.',cues:['Take a comfortable wide stance; turn the front foot outward.','Bend the front knee gently in the direction of your toes.','Extend your arms. Repeat on the other side.']}
];
let current='reach',filter='all',stream=null,landmarker=null,starting=false,runId=0,lastVideo=-1,lastDetect=0,lastFeedback=0,remaining=30,timerId=null,sceneApi=null;
function drawCards(){ $('poses').innerHTML=poses.filter(p=>filter==='all'||p.type===filter).map(p=>`<button class="pose-card ${p.id===current?'active':''}" data-pose="${p.id}" aria-pressed="${p.id===current}"><span class="pose-icon" aria-hidden="true">${p.icon}</span><span><strong>${p.name}</strong><small>${p.type==='yoga'?'Yoga':'Stretch'} · 30 sec</small></span><span class="arrow">↗</span></button>`).join('');document.querySelectorAll('[data-pose]').forEach(b=>b.onclick=()=>selectPose(b.dataset.pose));}
function selectPose(id){const p=poses.find(p=>p.id===id);if(!p)throw Error('Unknown movement');current=id;stopTimer();remaining=30;updateTimer();$('pose-tag').textContent=`${p.type.toUpperCase()} · ${p.area}`;$('pose-name').textContent=p.name;$('pose-description').textContent=p.description;$('cues').innerHTML=p.cues.map((c,i)=>`<div class="cue"><span>${i+1}</span>${c}</div>`).join('');drawCards();sceneApi?.setPose(id);setFeedback({state:'unknown',title:stream?'Find your starting position':'Ready when you are',text:stream?'Face the camera and keep your whole body visible.':'Turn on your camera to see your alignment feedback here.'});}
function setFeedback(r){document.querySelector('.feedback').className=`feedback ${r.state}`;$('feedback-title').textContent=r.title;$('feedback-text').textContent=r.text;$('feedback-icon').textContent=r.state==='good'?'✓':r.state==='warning'?'↗':'◌';}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));drawCards()});
$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=$('got-it').onclick=()=>$('help-dialog').close();
function updateTimer(){$('time').textContent=`00:${String(remaining).padStart(2,'0')}`;}
function stopTimer(){clearInterval(timerId);timerId=null;$('timer').textContent='▶';$('timer').setAttribute('aria-label','Start hold timer');}
$('timer').onclick=()=>{if(timerId){stopTimer();return}if(!remaining)remaining=30;$('timer').textContent='Ⅱ';$('timer').setAttribute('aria-label','Pause hold timer');timerId=setInterval(()=>{remaining--;updateTimer();if(!remaining){stopTimer();setFeedback({state:'unknown',title:'Take a breath',text:'Release gently. Rest or switch sides when you’re ready.'})}},1000);};
function stopCamera(){runId++;stream?.getTracks().forEach(t=>t.stop());stream=null;$('video').srcObject=null;$('video').hidden=$('overlay').hidden=true;$('three').hidden=false;$('stage-note').hidden=false;$('rotate').hidden=false;$('stage').classList.remove('live');$('mode').textContent='○   REFERENCE PREVIEW';$('camera').textContent='▣   Enable camera';$('camera-title').textContent='Your space. Your pace.';$('camera-sub').textContent='Enable your camera to get live alignment cues.';stopTimer();setFeedback({state:'unknown',title:'Camera is off',text:'Your reference guide is ready. You can restart whenever you like.'});}
$('camera').onclick=async()=>{if(stream){stopCamera();return}if(starting)return;starting=true;$('camera').disabled=true;$('camera').textContent='Connecting…';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access requires HTTPS or localhost in a supported browser.');stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},facingMode:'user'},audio:false});$('camera-sub').textContent='Preparing on-device pose tracking…';if(!landmarker){const {FilesetResolver,PoseLandmarker}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const files=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');landmarker=await PoseLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task'},runningMode:'VIDEO',numPoses:1,minPoseDetectionConfidence:.6,minPosePresenceConfidence:.6,minTrackingConfidence:.6});}
$('video').srcObject=stream;await $('video').play();$('video').hidden=$('overlay').hidden=false;$('three').hidden=true;$('stage-note').hidden=true;$('rotate').hidden=true;$('stage').classList.add('live');$('mode').textContent='●   LIVE · ON DEVICE';$('camera').textContent='Stop camera';$('camera-title').textContent='Make yourself comfortable.';$('camera-sub').textContent='Full body in frame · Face the camera';lastVideo=-1;const token=++runId;stream.getVideoTracks()[0].onended=()=>{if(stream)stopCamera()};requestAnimationFrame(t=>track(t,token));}catch(e){stopCamera();const msg=e.name==='NotAllowedError'?'Camera permission was declined. Allow access in your browser and try again.':e.name==='NotFoundError'?'No camera was found. Connect a camera and try again.':e.message||'Could not start tracking. Check your connection and try again.';$('camera-sub').textContent=msg;setFeedback({state:'warning',title:'Camera could not start',text:msg});}finally{starting=false;$('camera').disabled=false;}};
const connections=[[11,12],[11,13],[13,15],[12,14],[14,16],[11,23],[12,24],[23,24],[23,25],[25,27],[24,26],[26,28]];
function track(t,token){if(token!==runId||!stream)return;try{const v=$('video');if(v.readyState>=2&&v.currentTime!==lastVideo&&t-lastDetect>85){lastVideo=v.currentTime;lastDetect=t;const result=landmarker.detectForVideo(v,t);const c=$('overlay');c.width=v.videoWidth;c.height=v.videoHeight;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);const p=result.landmarks[0];if(p){ctx.strokeStyle='#d9f6a0';ctx.lineWidth=4;for(const[a,b]of connections){if(p[a].visibility<.65||p[b].visibility<.65)continue;ctx.beginPath();ctx.moveTo(p[a].x*c.width,p[a].y*c.height);ctx.lineTo(p[b].x*c.width,p[b].y*c.height);ctx.stroke();}ctx.fillStyle='#f7ffe9';for(const i of [...new Set(connections.flat())]){if(p[i].visibility<.65)continue;ctx.beginPath();ctx.arc(p[i].x*c.width,p[i].y*c.height,5,0,Math.PI*2);ctx.fill();}}
if(t-lastFeedback>650){lastFeedback=t;setFeedback(evaluate(current,p,v.videoWidth,v.videoHeight));}}requestAnimationFrame(t=>track(t,token));}catch(e){stopCamera();setFeedback({state:'warning',title:'Tracking paused',text:'Pose tracking encountered a problem. Restart the camera to try again.'});}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTimer();}});window.addEventListener('pagehide',stopCamera);
selectPose('reach');
async function initThree(){try{const THREE=await import('https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js');const host=$('three');const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(34,1,.1,100);camera.position.set(0,1.65,6.8);camera.lookAt(0,1.15,0);const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;host.append(renderer.domElement);scene.add(new THREE.HemisphereLight(0xffffff,0x6f7d59,2.5));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(-3,5,4);scene.add(light);const group=new THREE.Group();scene.add(group);const mat=new THREE.MeshStandardMaterial({color:0x6c8058,roughness:.65,metalness:.05});const jointmat=new THREE.MeshStandardMaterial({color:0xd8ecad,roughness:.55});const headmat=new THREE.MeshStandardMaterial({color:0x869974,roughness:.55});const floor=new THREE.Mesh(new THREE.CircleGeometry(1.4,80),new THREE.MeshBasicMaterial({color:0xafbda1,transparent:true,opacity:.28}));floor.rotation.x=-Math.PI/2;floor.position.y=.02;scene.add(floor);const rings=new THREE.Mesh(new THREE.RingGeometry(1.18,1.19,100),new THREE.MeshBasicMaterial({color:0x96aa81,side:THREE.DoubleSide,transparent:true,opacity:.5}));rings.rotation.x=-Math.PI/2;rings.position.y=.03;scene.add(rings);
const points={reach:[[-.23,1.7,0],[.23,1.7,0],[-.34,2.12,0],[.34,2.12,0],[-.25,2.55,0],[.25,2.55,0],[-.16,1.05,0],[.16,1.05,0],[-.2,.57,0],[.2,.57,0],[-.23,.12,.05],[.23,.12,.05]],mountain:[[-.23,1.7,0],[.23,1.7,0],[-.31,1.31,0],[.31,1.31,0],[-.36,.94,0],[.36,.94,0],[-.16,1.05,0],[.16,1.05,0],[-.2,.57,0],[.2,.57,0],[-.23,.12,.05],[.23,.12,.05]],side:[[-.45,1.68,0],[-.02,1.82,0],[-.58,1.3,0],[-.12,2.22,0],[-.45,.98,0],[-.49,2.48,0],[-.16,1.05,0],[.16,1.05,0],[-.22,.57,0],[.24,.57,0],[-.3,.12,.05],[.3,.12,.05]],warrior:[[-.23,1.62,0],[.23,1.62,0],[-.67,1.63,0],[.67,1.63,0],[-1.09,1.64,0],[1.09,1.64,0],[-.16,1,0],[.16,1,0],[-.67,.6,0],[.47,.57,0],[-.69,.12,.05],[.79,.12,.05]]};
const links=[[0,1],[0,2],[2,4],[1,3],[3,5],[0,6],[1,7],[6,7],[6,8],[8,10],[7,9],[9,11]];let target=points[current],coords=target.map(p=>new THREE.Vector3(...p));const joints=coords.map(()=>{const m=new THREE.Mesh(new THREE.SphereGeometry(.075,20,16),jointmat);group.add(m);return m});const bones=links.map(()=>{const m=new THREE.Mesh(new THREE.CylinderGeometry(.058,.067,1,16),mat);group.add(m);return m});const head=new THREE.Mesh(new THREE.SphereGeometry(.145,32,24),headmat);head.scale.y=1.18;group.add(head);const neck=new THREE.Mesh(new THREE.CylinderGeometry(.055,.07,.18,16),mat);group.add(neck);const torso=new THREE.Mesh(new THREE.SphereGeometry(1,28,20),mat);torso.scale.set(.22,.35,.12);group.add(torso);let rotation=0;$('rotate').onclick=()=>{rotation+=Math.PI/4};sceneApi={setPose(id){target=points[id]}};new ResizeObserver(()=>{const {width,height}=host.getBoundingClientRect();if(!width||!height)return;renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();}).observe(host);
renderer.setAnimationLoop(()=>{if(document.hidden||host.hidden)return;coords.forEach((v,i)=>{v.lerp(new THREE.Vector3(...target[i]),.08);joints[i].position.copy(v)});links.forEach(([a,b],i)=>{const d=new THREE.Vector3().subVectors(coords[b],coords[a]);bones[i].position.copy(coords[a]).add(coords[b]).multiplyScalar(.5);bones[i].scale.y=d.length();bones[i].quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize())});const shoulder=coords[0].clone().add(coords[1]).multiplyScalar(.5);head.position.copy(shoulder).add(new THREE.Vector3(0,.31,0));neck.position.copy(shoulder).add(new THREE.Vector3(0,.12,0));torso.position.copy(shoulder).add(coords[6].clone().add(coords[7]).multiplyScalar(.5)).multiplyScalar(.5);torso.rotation.z=current==='side'?.28:0;group.rotation.y+=(rotation-group.rotation.y)*.06;renderer.render(scene,camera)});
}catch(e){$('stage-note').innerHTML='3D guide could not load.<small>You can still follow the written cues or enable your camera.</small>';$('rotate').disabled=true;}}
initThree();
const lifecycle=new AbortController();if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_stretch',description:'Select a stretch or yoga reference without activating the camera.',inputSchema:{type:'object',properties:{id:{type:'string',enum:poses.map(p=>p.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.id!=='string'||!poses.some(p=>p.id===input.id))throw Error('Unknown movement');selectPose(input.id);return {selected:current,cameraActive:!!stream}}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort());
